INSERT INTO irResearchProject (id, title, status, budgetInitial, budgetSpent, startDate, endDate, leaderId, department, createdAt, updatedAt)
VALUES ('c7e86173-d686-44c0-8616-287edb1cc88b', 'การศึกษาทดลองแบบสุ่มถึงผลของการให้สเตียรอยด์ในช่วงระหว่างผ่าตัดจนถึงหลังผ่าตัดอย่างต่อเนื่องเทียบกับการให้สเตียรอยด์เพียงครั้งเดียวในช่วงระหว่างผ่าตัดต่ออาการปวดภายหลังการผ่าตัดในผู้ป่วยที่ได้รับการผ่าตัดรักษาโรคกระดูกสันหลังระดับเอวเสื่อม (The Effect of Combined Perioperative and Continuous Postoperative Corticosteroids Versus Single-Dose Perioperative Corticosteroids on Postoperative Pain in Degenerative Lumbar Spine Surgery: A Randomized controlled trial) COA No. 350/2025 IRB No. P3-0068/2568 วันที่รับรอง 15 กันยายน 2568', 'ONGOING', 50000.0, 0.0, '2026-02-11T00:00:00.000Z', '2026-02-11T00:00:00.000Z', 'user-1', 'Faculty of Medicine', datetime('now'), datetime('now'));

